namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    private const int MaxRatePoints = 10;

    public static int PayableCentsFor(LoyaltyTier tier, int subtotalCents)
    {
        var effectiveRatePoints = Math.Min(BaseRatePointsFor(tier) + OrderSizeBonusPointsFor(subtotalCents), MaxRatePoints);

        var discountCents = subtotalCents * effectiveRatePoints / 100;

        return subtotalCents - discountCents;
    }

    private static int BaseRatePointsFor(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 7,
        LoyaltyTier.Gold => 9,
        _ => throw new ArgumentOutOfRangeException(nameof(tier), tier, "Unsupported loyalty tier."),
    };

    private static int OrderSizeBonusPointsFor(int subtotalCents) => subtotalCents switch
    {
        < 5000 => 0,
        < 20000 => 1,
        _ => 3,
    };
}
EOF

